sys_script_client.script:
function onSubmit() {

    var assignmentGroup = g_form.getValue('assignment_group');
    var sys_id = g_form.getUniqueValue();
    var ga = new GlideAjax('GetUserAssignmentGroups');
    ga.addParam('sysparm_name', 'getUserAssignmentGroups');
    ga.addParam('sysparm_assignmentgroup', assignmentGroup);
    ga.addParam('sysparm_recordSysID', sys_id);
    //ga.getXML(Updategroup);
    try {
        ga.getXMLAnswer(Updategroup);
    } catch (error) {
        console.log('call Custody_UpdateAssignmentGroup failed!');
    } finally {
        g_form.setValue('assignment_group', assignmentGroup);
    }

    function Updategroup(response) {
        console.log('Testing response: ' + response);
        //var answer = response.responseXML.documentElement.getAttribute("answer");
        var answer = String(response);
        console.log('Testing answer: ' + answer);
        if (answer.indexOf(',') != -1) {
            var currentUserAssignmentGroups = answer.split(',');
            if (assignmentGroup && currentUserAssignmentGroups.indexOf(assignmentGroup) === -1) {
                if (currentUserAssignmentGroups.length > 1) {

                    g_form.clearValue('assignment_group');
                    g_form.setMandatory('assignment_group', true);

                    return false;
                } else {
                    g_form.setValue('assignment_group', currentUserAssignmentGroups[0]);

                }
            }
        } else {
            console.log('go to else: ' + assignmentGroup);
            g_form.setValue('assignment_group', assignmentGroup);
        }
        return true;
    }

}
